import{_ as a,a0 as p,w as d,s as i,I as t,x as n,a1 as s,A as r,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"命令行星期二——第七部分 | LCTT x X-CMD","titleTemplate":false,"description":"命令行星期二——第七部分 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行星期二——第七部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行星期二——第七部分 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140807 Command Line Tuesdays--Part Seven","title":"命令行星期二——第七部分","tag":"201408","desc":""},"relativePath":"201408/20140807 Command Line Tuesdays--Part Seven.md","filePath":"[post].md"}'),u={name:"201408/20140807 Command Line Tuesdays--Part Seven.md"};function m(g,e,f,T,x,h){const o=p("Link");return d(),i("div",null,[e[16]||(e[16]=t("h1",{id:"命令行星期二——第七部分",tabindex:"-1"},[n("命令行星期二——第七部分 "),t("a",{class:"header-anchor",href:"#命令行星期二——第七部分","aria-label":"Permalink to “命令行星期二——第七部分”"},"​")],-1)),e[17]||(e[17]=t("p",null,[n("嗨，极客们，我已经检查了我们的课程，今天我们在八章课程里的第七部分。这就是说下周二我们还有一次课程，但也是最后一次“命令行星期二”课程。所以，今天，我们讨论一些关于"),t("strong",null,"权限"),n("的问题！")],-1)),t("p",null,[e[1]||(e[1]=n("众所周知，一台机器可能会有多名用户共同使用。为了保证用户之间互不干扰，就需要分配不同的权限。我们已经讨论了文件权限的问题，你可以轻轻",-1)),s(o,{href:"1"},{default:r(()=>[...e[0]||(e[0]=[n("点此",-1)])]),_:1}),e[2]||(e[2]=n("回顾一下：",-1))]),e[18]||(e[18]=l(`<p><img src="http://linuxcommand.org/images/file_permissions.png" alt=""></p><h3 id="chmod" tabindex="-1">chmod <a class="header-anchor" href="#chmod" aria-label="Permalink to “chmod”">​</a></h3><p><strong>chmod</strong>命令被用来修改目录或者文件的权限。为了修改权限，首先你得输入chmod命令，之后你得输入规范的权限修改，然后你就可以把目录或者文件的权限修改成你想要的。这可以采用多种方式完成，但是肖茨先生喜欢八进制表示法。</p><p>把权限想象成一系列的位，每一个不为空的权限槽就是1，空的权限槽就是0。举个例子：</p><pre><code>rwx = 111

rw- = 110
</code></pre><p>等等</p><p>看一下二进制表示法：</p><pre><code>rwx = 111 --&gt; in binary = 7

rw- = 110 --&gt; in binary = 6
 
r-x = 101 --&gt; in binary = 5
 
r– = 100 --&gt; in binary = 4
</code></pre><p>现在，如果你想把一个文件的权限改为：文件所有者和文件所有组拥有读，写，执行权限，但是其他用户没有该文件任何权限，我们可以这样做：</p><pre><code>chmod 770 example_file
</code></pre><h3 id="su-和-sudo" tabindex="-1">su 和 sudo <a class="header-anchor" href="#su-和-sudo" aria-label="Permalink to “su 和 sudo”">​</a></h3><p>有些时候普通用户需要成为超级用户，这样才能完成一些任务（通常是一些安装软件任务）。为了暂时的获取超级用户权限，我们可以使用<strong>su</strong>程序，输入：</p><pre><code>su
</code></pre><p>输入你的超级用户密码，你就成为超级用户了。但是，警告：别忘记用一会之后（不需要的话）就退出超级用户模式。</p><p>在openSUSE和Ubuntu也其它的一些可选工具，它叫做sudo，sudo只是在某些方面和su不同，它是分配给制定用户的特殊命令，不像su，你可以用你自己用户的密码执行sudo，而不需要超级用户密码，举个例子：</p><pre><code>sudo zypper in goodiegoodie
</code></pre><h3 id="修改文件和组所有权" tabindex="-1">修改文件和组所有权 <a class="header-anchor" href="#修改文件和组所有权" aria-label="Permalink to “修改文件和组所有权”">​</a></h3><p>想要改变文件的所有者，你可以在超级用户模式下运行<strong>chown</strong>，举个例子，如果我想把文件的所有权从‘nenad’改为‘suse’，我可以这样做：</p><pre><code>su

[输入密码]

chown suse example_file
</code></pre><p>同样地，我也可以改变组的所有权，使用稍有不同的<strong>chgrp</strong>命令，很简单：</p><pre><code>chgrp suse_group example_file
</code></pre><h3 id="下一次" tabindex="-1">下一次 <a class="header-anchor" href="#下一次" aria-label="Permalink to “下一次”">​</a></h3><p>正如我所阐述的，下一次我们就会结束这个系列。在此之后，相信你会做出自己的选择，和我一起徜徉在终端的黑暗之中，只有一个绿色的闪烁光标作为灯塔。在那之前，极客们，记住</p><p>....享受更多的乐趣！</p><hr>`,25)),t("p",null,[e[4]||(e[4]=n("via: ",-1)),s(o,{href:"https://news.opensuse.org/2014/08/05/command-line-tuesdays-part-seven/"},{default:r(()=>[...e[3]||(e[3]=[n("https://news.opensuse.org/2014/08/05/command-line-tuesdays-part-seven/",-1)])]),_:1})]),t("p",null,[e[8]||(e[8]=n("作者：",-1)),s(o,{href:"https://news.opensuse.org/author/holden87/"},{default:r(()=>[...e[5]||(e[5]=[n("Nenad Latinović",-1)])]),_:1}),e[9]||(e[9]=n(" 译者：",-1)),s(o,{href:"https://github.com/su-kaiyao"},{default:r(()=>[...e[6]||(e[6]=[n("su-kaiyao",-1)])]),_:1}),e[10]||(e[10]=n(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:r(()=>[...e[7]||(e[7]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=n("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[11]||(e[11]=[n("LCTT",-1)])]),_:1}),e[14]||(e[14]=n(" 原创翻译，",-1)),s(o,{href:"http://linux.cn/"},{default:r(()=>[...e[12]||(e[12]=[n("Linux中国",-1)])]),_:1}),e[15]||(e[15]=n(" 荣誉推出",-1))])])}const L=a(u,[["render",m]]);export{y as __pageData,L as default};
